/// Why a byte string is not a HIR file this reader can use.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ReadError(pub &'static str);

impl std::fmt::Display for ReadError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "malformed HIR: {}", self.0)
    }
}

impl std::error::Error for ReadError {}

struct Cur<'a> {
    words: &'a [u32],
    at: usize,
}

impl Cur<'_> {
    fn u(&mut self) -> Result<u32, ReadError> {
        let x = *self
            .words
            .get(self.at)
            .ok_or(ReadError("truncated record"))?;
        self.at += 1;
        Ok(x)
    }

    fn flag(&mut self) -> Result<bool, ReadError> {
        match self.u()? {
            0 => Ok(false),
            1 => Ok(true),
            _ => Err(ReadError("a boolean is neither 0 nor 1")),
        }
    }

    fn f64(&mut self) -> Result<f64, ReadError> {
        let low = u64::from(self.u()?);
        let high = u64::from(self.u()?);
        Ok(f64::from_bits(low | high << 32))
    }
}

fn enum_at<T: Copy>(all: &[T], n: u32) -> Result<T, ReadError> {
    all.get(n as usize)
        .copied()
        .ok_or(ReadError("an enumeration value is out of range"))
}

struct Reader<'a> {
    nodes: &'a [u32],
    offsets: Vec<usize>,
    spans: &'a [u32],
    lists: &'a [u32],
}

impl<'a> Reader<'a> {
    fn list(&self, c: &mut Cur<'_>, size: usize) -> Result<(Cur<'a>, usize), ReadError> {
        let start = c.u()? as usize;
        let len = c.u()? as usize;
        let end = len.checked_mul(size).and_then(|n| n.checked_add(start));
        if end.is_none_or(|end| end > self.lists.len()) {
            return Err(ReadError("a list runs past the list section"));
        }
        Ok((
            Cur {
                words: self.lists,
                at: start,
            },
            len,
        ))
    }

    fn string(&self, c: &mut Cur<'_>) -> Result<JsString, ReadError> {
        let start = c.u()? as usize;
        let len = c.u()? as usize;
        if len > JsString::MAX_LEN {
            return Err(ReadError("a string is too long"));
        }
        let words = self
            .lists
            .get(start..start + len.div_ceil(2))
            .ok_or(ReadError("a string runs past the list section"))?;
        let units = words
            .iter()
            .flat_map(|w| [*w as u16, (*w >> 16) as u16])
            .take(len)
            .collect();
        Ok(JsString::from_owned_utf16(units))
    }

    // Node `n` (index plus 1) as a cursor after its kind word. A child is
    // written before its parent, so its index is below `limit`.
    fn node(&self, n: u32, limit: usize) -> Result<(usize, u32, Cur<'a>), ReadError> {
        let index = (n as usize)
            .checked_sub(1)
            .ok_or(ReadError("a node reference is 0"))?;
        if index >= limit {
            return Err(ReadError(
                "a node reference does not point to an earlier node",
            ));
        }
        let at = self.offsets[index];
        Ok((
            index,
            self.nodes[at],
            Cur {
                words: self.nodes,
                at: at + 1,
            },
        ))
    }

    fn span(&self, index: usize) -> Span {
        match self.spans.get(index * 3..index * 3 + 3) {
            Some(&[file, start, end]) => Span {
                file: FileRef(file),
                start,
                end,
            },
            _ => Span {
                file: FileRef(0),
                start: 0,
                end: 0,
            },
        }
    }
}

