fn r_type(r: &Reader<'_>, c: &mut Cur<'_>, limit: usize) -> Result<Type, ReadError> {
    Ok(match c.u()? {
        0 => {
            let repr = enum_at(NumRepr::ALL, c.u()?)?;
            Type::Number { repr }
        }
        1 => Type::String,
        2 => Type::Boolean,
        3 => Type::Null,
        4 => Type::Undefined,
        5 => {
            let value = Box::new(rn_literal(r, c.u()?, limit)?);
            Type::Literal { value }
        }
        6 => {
            let layout = LayoutRef(c.u()?);
            Type::Record { layout }
        }
        7 => {
            let fields = {
                let (mut l136, n) = r.list(c, 3)?;
                let mut v = Vec::with_capacity(n);
                for _ in 0..n {
                    let c = &mut l136;
                    v.push(r_shape_field(r, c, limit)?);
                }
                v
            };
            Type::Shape { fields }
        }
        8 => {
            let elem = TypeRef(c.u()?);
            Type::Array { elem }
        }
        9 => {
            let params = {
                let (mut l137, n) = r.list(c, 1)?;
                let mut v = Vec::with_capacity(n);
                for _ in 0..n {
                    let c = &mut l137;
                    v.push(TypeRef(c.u()?));
                }
                v
            };
            let rest = match c.u()? {
                0 => None,
                n => Some(TypeRef((n - 1))),
            };
            let ret = TypeRef(c.u()?);
            let async_ = c.flag()?;
            Type::Fn {
                params,
                rest,
                ret,
                async_,
            }
        }
        10 => {
            let layout = LayoutRef(c.u()?);
            let proto = match c.u()? {
                0 => None,
                n => Some(TypeRef((n - 1))),
            };
            Type::Class { layout, proto }
        }
        11 => {
            let members = {
                let (mut l138, n) = r.list(c, 1)?;
                let mut v = Vec::with_capacity(n);
                for _ in 0..n {
                    let c = &mut l138;
                    v.push(TypeRef(c.u()?));
                }
                v
            };
            let tag = match c.u()? {
                0 => None,
                n => Some(StringRef((n - 1))),
            };
            Type::Union { members, tag }
        }
        12 => Type::Dynamic,
        13 => {
            let base = TypeRef(c.u()?);
            let name = StringRef(c.u()?);
            Type::Nominal { base, name }
        }
        _ => return Err(ReadError("unknown Type kind")),
    })
}

