fn r_descriptor(r: &Reader<'_>, c: &mut Cur<'_>, limit: usize) -> Result<Descriptor, ReadError> {
    Ok(match c.u()? {
        0 => {
            let repr = enum_at(NumRepr::ALL, c.u()?)?;
            let min = {
                let present = c.flag()?;
                let x = c.f64()?;
                present.then_some(x)
            };
            let max = {
                let present = c.flag()?;
                let x = c.f64()?;
                present.then_some(x)
            };
            Descriptor::Number { repr, min, max }
        }
        1 => {
            let max_bytes = match c.u()? {
                0 => None,
                n => Some((n - 1)),
            };
            Descriptor::String { max_bytes }
        }
        2 => Descriptor::Boolean,
        3 => Descriptor::Null,
        4 => Descriptor::Undefined,
        5 => {
            let value = Box::new(rn_literal(r, c.u()?, limit)?);
            Descriptor::Literal { value }
        }
        6 => {
            let inner = DescriptorRef(c.u()?);
            Descriptor::Optional { inner }
        }
        7 => {
            let elem = DescriptorRef(c.u()?);
            let max_len = match c.u()? {
                0 => None,
                n => Some((n - 1)),
            };
            Descriptor::Array { elem, max_len }
        }
        8 => {
            let layout = LayoutRef(c.u()?);
            let fields = {
                let (mut l140, n) = r.list(c, 1)?;
                let mut v = Vec::with_capacity(n);
                for _ in 0..n {
                    let c = &mut l140;
                    v.push(DescriptorRef(c.u()?));
                }
                v
            };
            Descriptor::Record { layout, fields }
        }
        9 => {
            let tag = StringRef(c.u()?);
            let variants = {
                let (mut l141, n) = r.list(c, 2)?;
                let mut v = Vec::with_capacity(n);
                for _ in 0..n {
                    let c = &mut l141;
                    v.push(r_tagged_variant(r, c, limit)?);
                }
                v
            };
            Descriptor::Tagged { tag, variants }
        }
        10 => {
            let base = DescriptorRef(c.u()?);
            let name = StringRef(c.u()?);
            Descriptor::Nominal { base, name }
        }
        _ => return Err(ReadError("unknown Descriptor kind")),
    })
}

