fn r_class(r: &Reader<'_>, c: &mut Cur<'_>, limit: usize) -> Result<Class, ReadError> {
    let name = match c.u()? {
        0 => None,
        n => Some(DeclRef((n - 1))),
    };
    let extends = match c.u()? {
        0 => None,
        n => Some(Box::new(rn_expr(r, n, limit)?)),
    };
    let ctor = FunctionRef(c.u()?);
    let members = {
        let (mut l168, n) = r.list(c, 1)?;
        let mut v = Vec::with_capacity(n);
        for _ in 0..n {
            let c = &mut l168;
            v.push(rn_class_member(r, c.u()?, limit)?);
        }
        v
    };
    let instance_init = match c.u()? {
        0 => None,
        n => Some(FunctionRef((n - 1))),
    };
    let static_init = match c.u()? {
        0 => None,
        n => Some(FunctionRef((n - 1))),
    };
    let layout = match c.u()? {
        0 => None,
        n => Some(LayoutRef((n - 1))),
    };
    let span = r_span(r, c, limit)?;
    Ok(Class {
        name,
        extends,
        ctor,
        members,
        instance_init,
        static_init,
        layout,
        span,
    })
}

