fn rn_stmt(r: &Reader<'_>, n: u32, limit: usize) -> Result<Stmt, ReadError> {
    let (index, kind, mut cur) = r.node(n, limit)?;
    let (c, limit) = (&mut cur, index);
    let value = match kind {
        768 => {
            let e = Box::new(rn_expr(r, c.u()?, limit)?);
            StmtKind::Expr { e }
        }
        769 => {
            let decl = DeclRef(c.u()?);
            let init = match c.u()? {
                0 => None,
                n => Some(Box::new(rn_expr(r, n, limit)?)),
            };
            StmtKind::Declare { decl, init }
        }
        770 => {
            let pattern = Box::new(rn_pattern(r, c.u()?, limit)?);
            let init = Box::new(rn_expr(r, c.u()?, limit)?);
            let declaring = match c.u()? {
                0 => None,
                n => Some(enum_at(DeclaringKind::ALL, (n - 1))?),
            };
            StmtKind::Destructure {
                pattern,
                init,
                declaring,
            }
        }
        771 => {
            let body = r_block(r, c, limit)?;
            StmtKind::Block { body }
        }
        772 => {
            let test = Box::new(rn_expr(r, c.u()?, limit)?);
            let then = Box::new(rn_stmt(r, c.u()?, limit)?);
            let else_ = match c.u()? {
                0 => None,
                n => Some(Box::new(rn_stmt(r, n, limit)?)),
            };
            StmtKind::If { test, then, else_ }
        }
        773 => {
            let test = Box::new(rn_expr(r, c.u()?, limit)?);
            let body = Box::new(rn_stmt(r, c.u()?, limit)?);
            let label = c.u()?;
            StmtKind::While { test, body, label }
        }
        774 => {
            let body = Box::new(rn_stmt(r, c.u()?, limit)?);
            let test = Box::new(rn_expr(r, c.u()?, limit)?);
            let label = c.u()?;
            StmtKind::DoWhile { body, test, label }
        }
        775 => {
            let init = match c.u()? {
                0 => None,
                n => Some(Box::new(rn_stmt(r, n, limit)?)),
            };
            let test = match c.u()? {
                0 => None,
                n => Some(Box::new(rn_expr(r, n, limit)?)),
            };
            let update = match c.u()? {
                0 => None,
                n => Some(Box::new(rn_expr(r, n, limit)?)),
            };
            let body = Box::new(rn_stmt(r, c.u()?, limit)?);
            let label = c.u()?;
            let per_iteration = {
                let (mut l169, n) = r.list(c, 1)?;
                let mut v = Vec::with_capacity(n);
                for _ in 0..n {
                    let c = &mut l169;
                    v.push(DeclRef(c.u()?));
                }
                v
            };
            StmtKind::For {
                init,
                test,
                update,
                body,
                label,
                per_iteration,
            }
        }
        776 => {
            let target = Box::new(rn_for_target(r, c.u()?, limit)?);
            let init = match c.u()? {
                0 => None,
                n => Some(Box::new(rn_expr(r, n, limit)?)),
            };
            let obj = Box::new(rn_expr(r, c.u()?, limit)?);
            let body = Box::new(rn_stmt(r, c.u()?, limit)?);
            let label = c.u()?;
            StmtKind::ForIn {
                target,
                init,
                obj,
                body,
                label,
            }
        }
        777 => {
            let target = Box::new(rn_for_target(r, c.u()?, limit)?);
            let iter = Box::new(rn_expr(r, c.u()?, limit)?);
            let body = Box::new(rn_stmt(r, c.u()?, limit)?);
            let label = c.u()?;
            let await_ = c.flag()?;
            let array_fast = c.flag()?;
            StmtKind::ForOf {
                target,
                iter,
                body,
                label,
                await_,
                array_fast,
            }
        }
        778 => {
            let disc = Box::new(rn_expr(r, c.u()?, limit)?);
            let cases = {
                let (mut l170, n) = r.list(c, 3)?;
                let mut v = Vec::with_capacity(n);
                for _ in 0..n {
                    let c = &mut l170;
                    v.push(r_switch_case(r, c, limit)?);
                }
                v
            };
            let label = c.u()?;
            let exhaustive = c.flag()?;
            StmtKind::Switch {
                disc,
                cases,
                label,
                exhaustive,
            }
        }
        779 => {
            let label = c.u()?;
            StmtKind::Break { label }
        }
        780 => {
            let label = c.u()?;
            StmtKind::Continue { label }
        }
        781 => {
            let e = match c.u()? {
                0 => None,
                n => Some(Box::new(rn_expr(r, n, limit)?)),
            };
            StmtKind::Return { e }
        }
        782 => {
            let e = Box::new(rn_expr(r, c.u()?, limit)?);
            StmtKind::Throw { e }
        }
        783 => {
            let body = r_block(r, c, limit)?;
            let catch_param = match c.u()? {
                0 => None,
                n => Some(Box::new(rn_pattern(r, n, limit)?)),
            };
            let catch_body = {
                let present = c.flag()?;
                let x = r_block(r, c, limit)?;
                present.then_some(x)
            };
            let finally = {
                let present = c.flag()?;
                let x = r_block(r, c, limit)?;
                present.then_some(x)
            };
            let catch_default = match c.u()? {
                0 => None,
                n => Some(Box::new(rn_expr(r, n, limit)?)),
            };
            StmtKind::Try {
                body,
                catch_param,
                catch_body,
                finally,
                catch_default,
            }
        }
        784 => {
            let label = c.u()?;
            let body = Box::new(rn_stmt(r, c.u()?, limit)?);
            StmtKind::Labeled { label, body }
        }
        785 => {
            let decl = DeclRef(c.u()?);
            let fn_ = FunctionRef(c.u()?);
            let annex_b = match c.u()? {
                0 => None,
                n => Some(DeclRef((n - 1))),
            };
            StmtKind::FnDecl { decl, fn_, annex_b }
        }
        786 => {
            let decl = DeclRef(c.u()?);
            let cls = r_class(r, c, limit)?;
            StmtKind::ClassDecl { decl, cls }
        }
        787 => StmtKind::Debugger,
        788 => StmtKind::Empty,
        789 => {
            let key = Box::new(rn_field_key(r, c.u()?, limit)?);
            let value = match c.u()? {
                0 => None,
                n => Some(Box::new(rn_expr(r, n, limit)?)),
            };
            StmtKind::DefineField { key, value }
        }
        790 => {
            let decl = DeclRef(c.u()?);
            let value = match c.u()? {
                0 => None,
                n => Some(Box::new(rn_expr(r, n, limit)?)),
            };
            StmtKind::DefinePrivate { decl, value }
        }
        791 => {
            let fn_ = FunctionRef(c.u()?);
            StmtKind::StaticBlock { fn_ }
        }
        _ => return Err(ReadError("a node is not a Stmt")),
    };
    Ok(Stmt {
        kind: value,
        span: r.span(index),
    })
}

fn r_block(r: &Reader<'_>, c: &mut Cur<'_>, limit: usize) -> Result<Block, ReadError> {
    let stmts = {
        let (mut l171, n) = r.list(c, 1)?;
        let mut v = Vec::with_capacity(n);
        for _ in 0..n {
            let c = &mut l171;
            v.push(rn_stmt(r, c.u()?, limit)?);
        }
        v
    };
    let decls = {
        let (mut l172, n) = r.list(c, 1)?;
        let mut v = Vec::with_capacity(n);
        for _ in 0..n {
            let c = &mut l172;
            v.push(DeclRef(c.u()?));
        }
        v
    };
    Ok(Block { stmts, decls })
}

