fn d_descriptor(d: &mut Dumper<'_>, v: &Descriptor, ind: usize, head: String) {
    let mut parts: Vec<String> = Vec::new();
    let mut children: Vec<(&str, Child<'_>)> = Vec::new();
    let kind = match v {
        Descriptor::Number { repr, min, max } => {
            parts.push(format!("repr:{}", repr.as_str().to_string()));
            if let Some(x) = min {
                parts.push(format!("min:{}", fmt_f64(*x)));
            }
            if let Some(x) = max {
                parts.push(format!("max:{}", fmt_f64(*x)));
            }
            "number"
        }
        Descriptor::String { max_bytes } => {
            if let Some(x) = max_bytes {
                parts.push(format!("maxBytes:{}", x.to_string()));
            }
            "string"
        }
        Descriptor::Boolean => "boolean",
        Descriptor::Null => "null",
        Descriptor::Undefined => "undefined",
        Descriptor::Literal { value } => {
            children.push((
                "value",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_literal(d, value, ind, String::new())
                })),
            ));
            "literal"
        }
        Descriptor::Optional { inner } => {
            parts.push(format!("inner:{}", format!("#{}", inner.0)));
            "optional"
        }
        Descriptor::Array { elem, max_len } => {
            parts.push(format!("elem:{}", format!("#{}", elem.0)));
            if let Some(x) = max_len {
                parts.push(format!("maxLen:{}", x.to_string()));
            }
            "array"
        }
        Descriptor::Record { layout, fields } => {
            parts.push(format!("layout:{}", format!("#{}", layout.0)));
            parts.push(format!(
                "fields:{}",
                format!(
                    "[{}]",
                    fields
                        .iter()
                        .map(|x| format!("#{}", x.0))
                        .collect::<Vec<_>>()
                        .join(" ")
                )
            ));
            "record"
        }
        Descriptor::Tagged { tag, variants } => {
            parts.push(format!("tag:{}", d.string(*tag)));
            if variants.is_empty() {
                parts.push("variants:[]".to_string());
            } else {
                children.push((
                    "variants",
                    Child::Many(
                        variants
                            .iter()
                            .map(|x| -> Box<dyn Fn(&mut Dumper<'_>, usize) + '_> {
                                Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                                    d_tagged_variant(d, x, ind, String::new())
                                })
                            })
                            .collect(),
                    ),
                ));
            }
            "tagged"
        }
        Descriptor::Nominal { base, name } => {
            parts.push(format!("base:{}", format!("#{}", base.0)));
            parts.push(format!("name:{}", d.string(*name)));
            "nominal"
        }
    };
    let head = if head.is_empty() {
        kind.to_string()
    } else {
        format!("{head} {kind}")
    };
    d.record(ind, head, parts, children);
}

