fn d_function(d: &mut Dumper<'_>, v: &Function, ind: usize, head: String) {
    let mut parts: Vec<String> = Vec::new();
    let mut children: Vec<(&str, Child<'_>)> = Vec::new();
    if let Some(x) = (&v.name) {
        parts.push(format!("name:{}", d.string(*x)));
    }
    parts.push(format!("kind:{}", (&v.kind).as_str().to_string()));
    parts.push(format!("role:{}", (&v.role).as_str().to_string()));
    parts.push(format!("async:{}", (&v.async_).to_string()));
    parts.push(format!("generator:{}", (&v.generator).to_string()));
    parts.push(format!("strict:{}", (&v.strict).to_string()));
    if (&v.params).is_empty() {
        parts.push("params:[]".to_string());
    } else {
        children.push((
            "params",
            Child::Many(
                (&v.params)
                    .iter()
                    .map(|x| -> Box<dyn Fn(&mut Dumper<'_>, usize) + '_> {
                        Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                            d_param(d, x, ind, String::new())
                        })
                    })
                    .collect(),
            ),
        ));
    }
    if let Some(x) = (&v.rest) {
        children.push((
            "rest",
            Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                d_pattern(d, x, ind, String::new())
            })),
        ));
    }
    parts.push(format!("simpleParams:{}", (&v.simple_params).to_string()));
    children.push((
        "body",
        Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
            d_block(d, (&v.body), ind, String::new())
        })),
    ));
    parts.push(format!(
        "decls:{}",
        format!(
            "[{}]",
            (&v.decls)
                .iter()
                .map(|x| format!("#{}", x.0))
                .collect::<Vec<_>>()
                .join(" ")
        )
    ));
    parts.push(format!(
        "captures:{}",
        format!(
            "[{}]",
            (&v.captures)
                .iter()
                .map(|x| format!("#{}", x.0))
                .collect::<Vec<_>>()
                .join(" ")
        )
    ));
    parts.push(format!(
        "inner:{}",
        format!(
            "[{}]",
            (&v.inner)
                .iter()
                .map(|x| format!("#{}", x.0))
                .collect::<Vec<_>>()
                .join(" ")
        )
    ));
    parts.push(format!("usesThis:{}", (&v.uses_this).to_string()));
    parts.push(format!("usesArguments:{}", (&v.uses_arguments).to_string()));
    parts.push(format!(
        "usesNewTarget:{}",
        (&v.uses_new_target).to_string()
    ));
    parts.push(format!(
        "hasDirectEval:{}",
        (&v.has_direct_eval).to_string()
    ));
    parts.push(format!("homeObject:{}", (&v.home_object).to_string()));
    if !((&v.sig).is_none()) {
        if let Some(x) = (&v.sig) {
            children.push((
                "sig",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_signature(d, x, ind, String::new())
                })),
            ));
        }
    }
    if !((&v.effects).is_none()) {
        if let Some(x) = (&v.effects) {
            children.push((
                "effects",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_effects(d, x, ind, String::new())
                })),
            ));
        }
    }
    if d.spans {
        parts.push(format!(
            "span:{}",
            format!("{}:{}-{}", (&v.span).file.0, (&v.span).start, (&v.span).end)
        ));
    }
    parts.push(format!("length:{}", (&v.length).to_string()));
    children.push((
        "source",
        Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
            d_source_range(d, (&v.source), ind, String::new())
        })),
    ));
    if let Some(x) = (&v.self_) {
        parts.push(format!("self:{}", format!("#{}", x.0)));
    }
    if let Some(x) = (&v.arguments_decl) {
        parts.push(format!("argumentsDecl:{}", format!("#{}", x.0)));
    }
    if (&v.param_copies).is_empty() {
        parts.push("paramCopies:[]".to_string());
    } else {
        children.push((
            "paramCopies",
            Child::Many(
                (&v.param_copies)
                    .iter()
                    .map(|x| -> Box<dyn Fn(&mut Dumper<'_>, usize) + '_> {
                        Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                            d_param_copy(d, x, ind, String::new())
                        })
                    })
                    .collect(),
            ),
        ));
    }
    parts.push(format!("concise:{}", (&v.concise).to_string()));
    d.record(
        ind,
        if head.is_empty() {
            "Function".to_string()
        } else {
            head
        },
        parts,
        children,
    );
}

