fn d_expr(d: &mut Dumper<'_>, v: &Expr, ind: usize, head: String) {
    let mut parts: Vec<String> = Vec::new();
    let mut children: Vec<(&str, Child<'_>)> = Vec::new();
    let kind = match &v.kind {
        ExprKind::Const { value } => {
            parts.push(format!("value:{}", format!("#{}", value.0)));
            "const"
        }
        ExprKind::Str { value } => {
            parts.push(format!("value:{}", d.string(*value)));
            "str"
        }
        ExprKind::Bool { value } => {
            parts.push(format!("value:{}", value.to_string()));
            "bool"
        }
        ExprKind::Null => "null",
        ExprKind::Undefined => "undefined",
        ExprKind::Template { quasis, exprs } => {
            parts.push(format!(
                "quasis:{}",
                format!(
                    "[{}]",
                    quasis
                        .iter()
                        .map(|x| d.string(*x))
                        .collect::<Vec<_>>()
                        .join(" ")
                )
            ));
            if exprs.is_empty() {
                parts.push("exprs:[]".to_string());
            } else {
                children.push((
                    "exprs",
                    Child::Many(
                        exprs
                            .iter()
                            .map(|x| -> Box<dyn Fn(&mut Dumper<'_>, usize) + '_> {
                                Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                                    d_expr(d, x, ind, String::new())
                                })
                            })
                            .collect(),
                    ),
                ));
            }
            "template"
        }
        ExprKind::TaggedTemplate {
            tag,
            site,
            cooked,
            raw,
            exprs,
        } => {
            children.push((
                "tag",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_expr(d, tag, ind, String::new())
                })),
            ));
            parts.push(format!("site:{}", site.to_string()));
            parts.push(format!(
                "cooked:{}",
                format!(
                    "[{}]",
                    cooked
                        .iter()
                        .map(|x| x
                            .as_ref()
                            .map_or_else(|| "null".to_string(), |x| d.string(*x)))
                        .collect::<Vec<_>>()
                        .join(" ")
                )
            ));
            parts.push(format!(
                "raw:{}",
                format!(
                    "[{}]",
                    raw.iter()
                        .map(|x| d.string(*x))
                        .collect::<Vec<_>>()
                        .join(" ")
                )
            ));
            if exprs.is_empty() {
                parts.push("exprs:[]".to_string());
            } else {
                children.push((
                    "exprs",
                    Child::Many(
                        exprs
                            .iter()
                            .map(|x| -> Box<dyn Fn(&mut Dumper<'_>, usize) + '_> {
                                Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                                    d_expr(d, x, ind, String::new())
                                })
                            })
                            .collect(),
                    ),
                ));
            }
            "taggedTemplate"
        }
        ExprKind::Array { items } => {
            if items.is_empty() {
                parts.push("items:[]".to_string());
            } else {
                children.push((
                    "items",
                    Child::Many(
                        items
                            .iter()
                            .map(|x| -> Box<dyn Fn(&mut Dumper<'_>, usize) + '_> {
                                Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                                    d_array_item(d, x, ind, String::new())
                                })
                            })
                            .collect(),
                    ),
                ));
            }
            "array"
        }
        ExprKind::Object { props } => {
            if props.is_empty() {
                parts.push("props:[]".to_string());
            } else {
                children.push((
                    "props",
                    Child::Many(
                        props
                            .iter()
                            .map(|x| -> Box<dyn Fn(&mut Dumper<'_>, usize) + '_> {
                                Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                                    d_obj_prop(d, x, ind, String::new())
                                })
                            })
                            .collect(),
                    ),
                ));
            }
            "object"
        }
        ExprKind::Fn { fn_ } => {
            parts.push(format!("fn:{}", format!("#{}", fn_.0)));
            "fn"
        }
        ExprKind::Class { cls } => {
            children.push((
                "cls",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_class(d, cls, ind, String::new())
                })),
            ));
            "class"
        }
        ExprKind::Decl { decl } => {
            parts.push(format!("decl:{}", format!("#{}", decl.0)));
            "decl"
        }
        ExprKind::This { decl } => {
            parts.push(format!("decl:{}", format!("#{}", decl.0)));
            "this"
        }
        ExprKind::NewTarget { decl } => {
            parts.push(format!("decl:{}", format!("#{}", decl.0)));
            "newTarget"
        }
        ExprKind::ImportMeta => "importMeta",
        ExprKind::SuperMember { prop, this, home } => {
            children.push((
                "prop",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_prop_key(d, prop, ind, String::new())
                })),
            ));
            parts.push(format!("this:{}", format!("#{}", this.0)));
            parts.push(format!("home:{}", format!("#{}", home.0)));
            "superMember"
        }
        ExprKind::Member {
            obj,
            prop,
            optional,
            layout,
            field,
        } => {
            children.push((
                "obj",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_expr(d, obj, ind, String::new())
                })),
            ));
            children.push((
                "prop",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_prop_key(d, prop, ind, String::new())
                })),
            ));
            parts.push(format!("optional:{}", optional.to_string()));
            if !(layout.is_none()) {
                if let Some(x) = layout {
                    parts.push(format!("layout:{}", format!("#{}", x.0)));
                }
            }
            if !(field.is_none()) {
                if let Some(x) = field {
                    parts.push(format!("field:{}", x.to_string()));
                }
            }
            "member"
        }
        ExprKind::Unary { op, e } => {
            parts.push(format!("op:{}", op.as_str().to_string()));
            children.push((
                "e",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_expr(d, e, ind, String::new())
                })),
            ));
            "unary"
        }
        ExprKind::Update { op, prefix, target } => {
            parts.push(format!("op:{}", op.as_str().to_string()));
            parts.push(format!("prefix:{}", prefix.to_string()));
            children.push((
                "target",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_target(d, target, ind, String::new())
                })),
            ));
            "update"
        }
        ExprKind::Binary { op, l, r, numeric } => {
            parts.push(format!("op:{}", op.as_str().to_string()));
            children.push((
                "l",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_expr(d, l, ind, String::new())
                })),
            ));
            children.push((
                "r",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_expr(d, r, ind, String::new())
                })),
            ));
            if !(numeric.is_none()) {
                if let Some(x) = numeric {
                    parts.push(format!("numeric:{}", x.as_str().to_string()));
                }
            }
            "binary"
        }
        ExprKind::Logical { op, l, r } => {
            parts.push(format!("op:{}", op.as_str().to_string()));
            children.push((
                "l",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_expr(d, l, ind, String::new())
                })),
            ));
            children.push((
                "r",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_expr(d, r, ind, String::new())
                })),
            ));
            "logical"
        }
        ExprKind::Cond { test, then, else_ } => {
            children.push((
                "test",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_expr(d, test, ind, String::new())
                })),
            ));
            children.push((
                "then",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_expr(d, then, ind, String::new())
                })),
            ));
            children.push((
                "else",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_expr(d, else_, ind, String::new())
                })),
            ));
            "cond"
        }
        ExprKind::Assign { op, target, value } => {
            parts.push(format!("op:{}", op.as_str().to_string()));
            children.push((
                "target",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_target(d, target, ind, String::new())
                })),
            ));
            children.push((
                "value",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_expr(d, value, ind, String::new())
                })),
            ));
            "assign"
        }
        ExprKind::Seq { exprs } => {
            if exprs.is_empty() {
                parts.push("exprs:[]".to_string());
            } else {
                children.push((
                    "exprs",
                    Child::Many(
                        exprs
                            .iter()
                            .map(|x| -> Box<dyn Fn(&mut Dumper<'_>, usize) + '_> {
                                Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                                    d_expr(d, x, ind, String::new())
                                })
                            })
                            .collect(),
                    ),
                ));
            }
            "seq"
        }
        ExprKind::Call {
            callee,
            args,
            optional,
            direct,
            intrinsic,
            direct_eval,
        } => {
            children.push((
                "callee",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_expr(d, callee, ind, String::new())
                })),
            ));
            if args.is_empty() {
                parts.push("args:[]".to_string());
            } else {
                children.push((
                    "args",
                    Child::Many(
                        args.iter()
                            .map(|x| -> Box<dyn Fn(&mut Dumper<'_>, usize) + '_> {
                                Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                                    d_arg(d, x, ind, String::new())
                                })
                            })
                            .collect(),
                    ),
                ));
            }
            parts.push(format!("optional:{}", optional.to_string()));
            if !(direct.is_none()) {
                if let Some(x) = direct {
                    parts.push(format!("direct:{}", format!("#{}", x.0)));
                }
            }
            if !(intrinsic.is_none()) {
                if let Some(x) = intrinsic {
                    parts.push(format!("intrinsic:{}", d.string(*x)));
                }
            }
            parts.push(format!("directEval:{}", direct_eval.to_string()));
            "call"
        }
        ExprKind::New {
            callee,
            args,
            direct,
        } => {
            children.push((
                "callee",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_expr(d, callee, ind, String::new())
                })),
            ));
            if args.is_empty() {
                parts.push("args:[]".to_string());
            } else {
                children.push((
                    "args",
                    Child::Many(
                        args.iter()
                            .map(|x| -> Box<dyn Fn(&mut Dumper<'_>, usize) + '_> {
                                Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                                    d_arg(d, x, ind, String::new())
                                })
                            })
                            .collect(),
                    ),
                ));
            }
            if !(direct.is_none()) {
                if let Some(x) = direct {
                    parts.push(format!("direct:{}", format!("#{}", x.0)));
                }
            }
            "new"
        }
        ExprKind::SuperCall {
            args,
            this,
            new_target,
            func,
        } => {
            if args.is_empty() {
                parts.push("args:[]".to_string());
            } else {
                children.push((
                    "args",
                    Child::Many(
                        args.iter()
                            .map(|x| -> Box<dyn Fn(&mut Dumper<'_>, usize) + '_> {
                                Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                                    d_arg(d, x, ind, String::new())
                                })
                            })
                            .collect(),
                    ),
                ));
            }
            parts.push(format!("this:{}", format!("#{}", this.0)));
            parts.push(format!("newTarget:{}", format!("#{}", new_target.0)));
            parts.push(format!("func:{}", format!("#{}", func.0)));
            "superCall"
        }
        ExprKind::Import { spec, options } => {
            children.push((
                "spec",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_expr(d, spec, ind, String::new())
                })),
            ));
            if let Some(x) = options {
                children.push((
                    "options",
                    Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                        d_expr(d, x, ind, String::new())
                    })),
                ));
            }
            "import"
        }
        ExprKind::Yield { e, delegate } => {
            if let Some(x) = e {
                children.push((
                    "e",
                    Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                        d_expr(d, x, ind, String::new())
                    })),
                ));
            }
            parts.push(format!("delegate:{}", delegate.to_string()));
            "yield"
        }
        ExprKind::Await { e } => {
            children.push((
                "e",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_expr(d, e, ind, String::new())
                })),
            ));
            "await"
        }
        ExprKind::Decode { desc, e } => {
            parts.push(format!("desc:{}", format!("#{}", desc.0)));
            children.push((
                "e",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_expr(d, e, ind, String::new())
                })),
            ));
            "decode"
        }
        ExprKind::Scratch { elem, body } => {
            parts.push(format!("elem:{}", format!("#{}", elem.0)));
            parts.push(format!("body:{}", format!("#{}", body.0)));
            "scratch"
        }
        ExprKind::OptionalChain { e } => {
            children.push((
                "e",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_expr(d, e, ind, String::new())
                })),
            ));
            "optionalChain"
        }
        ExprKind::PrivateIn { name, obj } => {
            parts.push(format!("name:{}", format!("#{}", name.0)));
            children.push((
                "obj",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_expr(d, obj, ind, String::new())
                })),
            ));
            "privateIn"
        }
        ExprKind::Named { name, e } => {
            parts.push(format!("name:{}", d.string(*name)));
            children.push((
                "e",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_expr(d, e, ind, String::new())
                })),
            ));
            "named"
        }
    };
    if !((&v.ty).0 == 0) {
        parts.push(format!("ty:{}", format!("#{}", (&v.ty).0)));
    }
    if d.spans {
        parts.push(format!(
            "span:{}",
            format!("{}:{}-{}", (&v.span).file.0, (&v.span).start, (&v.span).end)
        ));
    }
    let head = if head.is_empty() {
        kind.to_string()
    } else {
        format!("{head} {kind}")
    };
    d.record(ind, head, parts, children);
}

