fn d_stmt(d: &mut Dumper<'_>, v: &Stmt, ind: usize, head: String) {
    let mut parts: Vec<String> = Vec::new();
    let mut children: Vec<(&str, Child<'_>)> = Vec::new();
    let kind = match &v.kind {
        StmtKind::Expr { e } => {
            children.push((
                "e",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_expr(d, e, ind, String::new())
                })),
            ));
            "expr"
        }
        StmtKind::Declare { decl, init } => {
            parts.push(format!("decl:{}", format!("#{}", decl.0)));
            if let Some(x) = init {
                children.push((
                    "init",
                    Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                        d_expr(d, x, ind, String::new())
                    })),
                ));
            }
            "declare"
        }
        StmtKind::Destructure {
            pattern,
            init,
            declaring,
        } => {
            children.push((
                "pattern",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_pattern(d, pattern, ind, String::new())
                })),
            ));
            children.push((
                "init",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_expr(d, init, ind, String::new())
                })),
            ));
            if let Some(x) = declaring {
                parts.push(format!("declaring:{}", x.as_str().to_string()));
            }
            "destructure"
        }
        StmtKind::Block { body } => {
            children.push((
                "body",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_block(d, body, ind, String::new())
                })),
            ));
            "block"
        }
        StmtKind::If { test, then, else_ } => {
            children.push((
                "test",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_expr(d, test, ind, String::new())
                })),
            ));
            children.push((
                "then",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_stmt(d, then, ind, String::new())
                })),
            ));
            if let Some(x) = else_ {
                children.push((
                    "else",
                    Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                        d_stmt(d, x, ind, String::new())
                    })),
                ));
            }
            "if"
        }
        StmtKind::While { test, body, label } => {
            children.push((
                "test",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_expr(d, test, ind, String::new())
                })),
            ));
            children.push((
                "body",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_stmt(d, body, ind, String::new())
                })),
            ));
            parts.push(format!("label:{}", label.to_string()));
            "while"
        }
        StmtKind::DoWhile { body, test, label } => {
            children.push((
                "body",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_stmt(d, body, ind, String::new())
                })),
            ));
            children.push((
                "test",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_expr(d, test, ind, String::new())
                })),
            ));
            parts.push(format!("label:{}", label.to_string()));
            "doWhile"
        }
        StmtKind::For {
            init,
            test,
            update,
            body,
            label,
            per_iteration,
        } => {
            if let Some(x) = init {
                children.push((
                    "init",
                    Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                        d_stmt(d, x, ind, String::new())
                    })),
                ));
            }
            if let Some(x) = test {
                children.push((
                    "test",
                    Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                        d_expr(d, x, ind, String::new())
                    })),
                ));
            }
            if let Some(x) = update {
                children.push((
                    "update",
                    Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                        d_expr(d, x, ind, String::new())
                    })),
                ));
            }
            children.push((
                "body",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_stmt(d, body, ind, String::new())
                })),
            ));
            parts.push(format!("label:{}", label.to_string()));
            parts.push(format!(
                "perIteration:{}",
                format!(
                    "[{}]",
                    per_iteration
                        .iter()
                        .map(|x| format!("#{}", x.0))
                        .collect::<Vec<_>>()
                        .join(" ")
                )
            ));
            "for"
        }
        StmtKind::ForIn {
            target,
            init,
            obj,
            body,
            label,
        } => {
            children.push((
                "target",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_for_target(d, target, ind, String::new())
                })),
            ));
            if let Some(x) = init {
                children.push((
                    "init",
                    Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                        d_expr(d, x, ind, String::new())
                    })),
                ));
            }
            children.push((
                "obj",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_expr(d, obj, ind, String::new())
                })),
            ));
            children.push((
                "body",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_stmt(d, body, ind, String::new())
                })),
            ));
            parts.push(format!("label:{}", label.to_string()));
            "forIn"
        }
        StmtKind::ForOf {
            target,
            iter,
            body,
            label,
            await_,
            array_fast,
        } => {
            children.push((
                "target",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_for_target(d, target, ind, String::new())
                })),
            ));
            children.push((
                "iter",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_expr(d, iter, ind, String::new())
                })),
            ));
            children.push((
                "body",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_stmt(d, body, ind, String::new())
                })),
            ));
            parts.push(format!("label:{}", label.to_string()));
            parts.push(format!("await:{}", await_.to_string()));
            if !(!*array_fast) {
                parts.push(format!("arrayFast:{}", array_fast.to_string()));
            }
            "forOf"
        }
        StmtKind::Switch {
            disc,
            cases,
            label,
            exhaustive,
        } => {
            children.push((
                "disc",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_expr(d, disc, ind, String::new())
                })),
            ));
            if cases.is_empty() {
                parts.push("cases:[]".to_string());
            } else {
                children.push((
                    "cases",
                    Child::Many(
                        cases
                            .iter()
                            .map(|x| -> Box<dyn Fn(&mut Dumper<'_>, usize) + '_> {
                                Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                                    d_switch_case(d, x, ind, String::new())
                                })
                            })
                            .collect(),
                    ),
                ));
            }
            parts.push(format!("label:{}", label.to_string()));
            if !(!*exhaustive) {
                parts.push(format!("exhaustive:{}", exhaustive.to_string()));
            }
            "switch"
        }
        StmtKind::Break { label } => {
            parts.push(format!("label:{}", label.to_string()));
            "break"
        }
        StmtKind::Continue { label } => {
            parts.push(format!("label:{}", label.to_string()));
            "continue"
        }
        StmtKind::Return { e } => {
            if let Some(x) = e {
                children.push((
                    "e",
                    Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                        d_expr(d, x, ind, String::new())
                    })),
                ));
            }
            "return"
        }
        StmtKind::Throw { e } => {
            children.push((
                "e",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_expr(d, e, ind, String::new())
                })),
            ));
            "throw"
        }
        StmtKind::Try {
            body,
            catch_param,
            catch_body,
            finally,
            catch_default,
        } => {
            children.push((
                "body",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_block(d, body, ind, String::new())
                })),
            ));
            if let Some(x) = catch_param {
                children.push((
                    "catchParam",
                    Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                        d_pattern(d, x, ind, String::new())
                    })),
                ));
            }
            if let Some(x) = catch_body {
                children.push((
                    "catchBody",
                    Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                        d_block(d, x, ind, String::new())
                    })),
                ));
            }
            if let Some(x) = finally {
                children.push((
                    "finally",
                    Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                        d_block(d, x, ind, String::new())
                    })),
                ));
            }
            if let Some(x) = catch_default {
                children.push((
                    "catchDefault",
                    Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                        d_expr(d, x, ind, String::new())
                    })),
                ));
            }
            "try"
        }
        StmtKind::Labeled { label, body } => {
            parts.push(format!("label:{}", label.to_string()));
            children.push((
                "body",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_stmt(d, body, ind, String::new())
                })),
            ));
            "labeled"
        }
        StmtKind::FnDecl { decl, fn_, annex_b } => {
            parts.push(format!("decl:{}", format!("#{}", decl.0)));
            parts.push(format!("fn:{}", format!("#{}", fn_.0)));
            if let Some(x) = annex_b {
                parts.push(format!("annexB:{}", format!("#{}", x.0)));
            }
            "fnDecl"
        }
        StmtKind::ClassDecl { decl, cls } => {
            parts.push(format!("decl:{}", format!("#{}", decl.0)));
            children.push((
                "cls",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_class(d, cls, ind, String::new())
                })),
            ));
            "classDecl"
        }
        StmtKind::Debugger => "debugger",
        StmtKind::Empty => "empty",
        StmtKind::DefineField { key, value } => {
            children.push((
                "key",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_field_key(d, key, ind, String::new())
                })),
            ));
            if let Some(x) = value {
                children.push((
                    "value",
                    Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                        d_expr(d, x, ind, String::new())
                    })),
                ));
            }
            "defineField"
        }
        StmtKind::DefinePrivate { decl, value } => {
            parts.push(format!("decl:{}", format!("#{}", decl.0)));
            if let Some(x) = value {
                children.push((
                    "value",
                    Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                        d_expr(d, x, ind, String::new())
                    })),
                ));
            }
            "definePrivate"
        }
        StmtKind::StaticBlock { fn_ } => {
            parts.push(format!("fn:{}", format!("#{}", fn_.0)));
            "staticBlock"
        }
    };
    if d.spans {
        parts.push(format!(
            "span:{}",
            format!("{}:{}-{}", (&v.span).file.0, (&v.span).start, (&v.span).end)
        ));
    }
    let head = if head.is_empty() {
        kind.to_string()
    } else {
        format!("{head} {kind}")
    };
    d.record(ind, head, parts, children);
}

fn d_block(d: &mut Dumper<'_>, v: &Block, ind: usize, head: String) {
    let mut parts: Vec<String> = Vec::new();
    let mut children: Vec<(&str, Child<'_>)> = Vec::new();
    if (&v.stmts).is_empty() {
        parts.push("stmts:[]".to_string());
    } else {
        children.push((
            "stmts",
            Child::Many(
                (&v.stmts)
                    .iter()
                    .map(|x| -> Box<dyn Fn(&mut Dumper<'_>, usize) + '_> {
                        Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                            d_stmt(d, x, ind, String::new())
                        })
                    })
                    .collect(),
            ),
        ));
    }
    parts.push(format!(
        "decls:{}",
        format!(
            "[{}]",
            (&v.decls)
                .iter()
                .map(|x| format!("#{}", x.0))
                .collect::<Vec<_>>()
                .join(" ")
        )
    ));
    d.record(
        ind,
        if head.is_empty() {
            "Block".to_string()
        } else {
            head
        },
        parts,
        children,
    );
}

fn d_switch_case(d: &mut Dumper<'_>, v: &SwitchCase, ind: usize, head: String) {
    let mut parts: Vec<String> = Vec::new();
    let mut children: Vec<(&str, Child<'_>)> = Vec::new();
    if let Some(x) = (&v.test) {
        children.push((
            "test",
            Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                d_expr(d, x, ind, String::new())
            })),
        ));
    }
    if (&v.body).is_empty() {
        parts.push("body:[]".to_string());
    } else {
        children.push((
            "body",
            Child::Many(
                (&v.body)
                    .iter()
                    .map(|x| -> Box<dyn Fn(&mut Dumper<'_>, usize) + '_> {
                        Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                            d_stmt(d, x, ind, String::new())
                        })
                    })
                    .collect(),
            ),
        ));
    }
    d.record(
        ind,
        if head.is_empty() {
            "SwitchCase".to_string()
        } else {
            head
        },
        parts,
        children,
    );
}

fn d_for_target(d: &mut Dumper<'_>, v: &ForTarget, ind: usize, head: String) {
    let mut parts: Vec<String> = Vec::new();
    let mut children: Vec<(&str, Child<'_>)> = Vec::new();
    let kind = match v {
        ForTarget::Assign { t } => {
            children.push((
                "t",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_target(d, t, ind, String::new())
                })),
            ));
            "assign"
        }
        ForTarget::Declare { pattern } => {
            children.push((
                "pattern",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_pattern(d, pattern, ind, String::new())
                })),
            ));
            "declare"
        }
    };
    let head = if head.is_empty() {
        kind.to_string()
    } else {
        format!("{head} {kind}")
    };
    d.record(ind, head, parts, children);
}

fn d_pattern(d: &mut Dumper<'_>, v: &Pattern, ind: usize, head: String) {
    let mut parts: Vec<String> = Vec::new();
    let mut children: Vec<(&str, Child<'_>)> = Vec::new();
    let kind = match &v.kind {
        PatternKind::Decl { decl } => {
            parts.push(format!("decl:{}", format!("#{}", decl.0)));
            "decl"
        }
        PatternKind::Target { t } => {
            children.push((
                "t",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_target(d, t, ind, String::new())
                })),
            ));
            "target"
        }
        PatternKind::Object { props, rest } => {
            if props.is_empty() {
                parts.push("props:[]".to_string());
            } else {
                children.push((
                    "props",
                    Child::Many(
                        props
                            .iter()
                            .map(|x| -> Box<dyn Fn(&mut Dumper<'_>, usize) + '_> {
                                Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                                    d_pattern_prop(d, x, ind, String::new())
                                })
                            })
                            .collect(),
                    ),
                ));
            }
            if let Some(x) = rest {
                children.push((
                    "rest",
                    Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                        d_pattern(d, x, ind, String::new())
                    })),
                ));
            }
            "object"
        }
        PatternKind::Array { items, rest } => {
            if items.is_empty() {
                parts.push("items:[]".to_string());
            } else {
                children.push((
                    "items",
                    Child::Many(
                        items
                            .iter()
                            .map(|x| -> Box<dyn Fn(&mut Dumper<'_>, usize) + '_> {
                                Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                                    d_pattern_item(d, x, ind, String::new())
                                })
                            })
                            .collect(),
                    ),
                ));
            }
            if let Some(x) = rest {
                children.push((
                    "rest",
                    Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                        d_pattern(d, x, ind, String::new())
                    })),
                ));
            }
            "array"
        }
    };
    if !((&v.ty).0 == 0) {
        parts.push(format!("ty:{}", format!("#{}", (&v.ty).0)));
    }
    if d.spans {
        parts.push(format!(
            "span:{}",
            format!("{}:{}-{}", (&v.span).file.0, (&v.span).start, (&v.span).end)
        ));
    }
    let head = if head.is_empty() {
        kind.to_string()
    } else {
        format!("{head} {kind}")
    };
    d.record(ind, head, parts, children);
}

fn d_pattern_prop(d: &mut Dumper<'_>, v: &PatternProp, ind: usize, head: String) {
    let mut parts: Vec<String> = Vec::new();
    let mut children: Vec<(&str, Child<'_>)> = Vec::new();
    children.push((
        "key",
        Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
            d_prop_key(d, (&v.key), ind, String::new())
        })),
    ));
    children.push((
        "value",
        Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
            d_pattern(d, (&v.value), ind, String::new())
        })),
    ));
    if let Some(x) = (&v.default) {
        children.push((
            "default",
            Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                d_expr(d, x, ind, String::new())
            })),
        ));
    }
    d.record(
        ind,
        if head.is_empty() {
            "PatternProp".to_string()
        } else {
            head
        },
        parts,
        children,
    );
}

fn d_pattern_item(d: &mut Dumper<'_>, v: &PatternItem, ind: usize, head: String) {
    let mut parts: Vec<String> = Vec::new();
    let mut children: Vec<(&str, Child<'_>)> = Vec::new();
    let kind = match v {
        PatternItem::Item { p, default } => {
            children.push((
                "p",
                Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                    d_pattern(d, p, ind, String::new())
                })),
            ));
            if let Some(x) = default {
                children.push((
                    "default",
                    Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                        d_expr(d, x, ind, String::new())
                    })),
                ));
            }
            "item"
        }
        PatternItem::Hole => "hole",
    };
    let head = if head.is_empty() {
        kind.to_string()
    } else {
        format!("{head} {kind}")
    };
    d.record(ind, head, parts, children);
}

/// The text form of `program`, without spans.
#[must_use]
pub fn dump(program: &Program) -> String {
    dump_with(program, DumpOptions::default())
}

/// The text form of `program`.
#[must_use]
pub fn dump_with(program: &Program, options: DumpOptions) -> String {
    let v = program;
    let mut d = Dumper {
        strings: &program.strings,
        spans: options.spans,
        out: String::new(),
    };
    {
        let d = &mut d;
        let mut parts: Vec<String> = Vec::new();
        let mut children: Vec<(&str, Child<'_>)> = Vec::new();
        parts.push(format!("version:{}", (&v.version).to_string()));
        children.push((
            "unit",
            Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                d_unit(d, (&v.unit), ind, String::new())
            })),
        ));
        children.push((
            "entry",
            Child::One(Box::new(move |d: &mut Dumper<'_>, ind: usize| {
                d_entry(d, (&v.entry), ind, String::new())
            })),
        ));
        d.record(0, "program".to_string(), parts, children);
    }
    for (i, x) in v.files.iter().enumerate() {
        d_file(&mut d, x, 0, format!("file #{i}"));
    }
    for (i, x) in v.strings.iter().enumerate() {
        d.record(0, format!("string #{i}"), vec![quote(x)], Vec::new());
    }
    for (i, x) in v.consts.iter().enumerate() {
        d_const(&mut d, x, 0, format!("const #{i}"));
    }
    for (i, x) in v.types.iter().enumerate() {
        d_type(&mut d, x, 0, format!("type #{i}"));
    }
    for (i, x) in v.layouts.iter().enumerate() {
        d_layout(&mut d, x, 0, format!("layout #{i}"));
    }
    for (i, x) in v.descriptors.iter().enumerate() {
        d_descriptor(&mut d, x, 0, format!("descriptor #{i}"));
    }
    for (i, x) in v.decls.iter().enumerate() {
        d_decl(&mut d, x, 0, format!("decl #{i}"));
    }
    for (i, x) in v.functions.iter().enumerate() {
        d_function(&mut d, x, 0, format!("fn #{i}"));
    }
    for (i, x) in v.modules.iter().enumerate() {
        d_module(&mut d, x, 0, format!("module #{i}"));
    }
    d.out
}

// ---- strip ----

fn s_decl(v: &mut Decl) {
    *(&mut v.ty) = TypeRef(0);
}

fn s_function(v: &mut Function) {
    for x in (&mut v.params).iter_mut() {
        s_param(x);
    }
    if let Some(x) = (&mut v.rest).as_mut() {
        s_pattern(x);
    }
    s_block((&mut v.body));
    *(&mut v.sig) = None;
    *(&mut v.effects) = None;
}

fn s_param(v: &mut Param) {
    s_pattern((&mut v.pattern));
    if let Some(x) = (&mut v.default).as_mut() {
        s_expr(x);
    }
}

fn s_expr(v: &mut Expr) {
    match &mut v.kind {
        ExprKind::Const { value } => {}
        ExprKind::Str { value } => {}
        ExprKind::Bool { value } => {}
        ExprKind::Null => {}
        ExprKind::Undefined => {}
        ExprKind::Template { quasis, exprs } => {
            for x in exprs.iter_mut() {
                s_expr(x);
            }
        }
        ExprKind::TaggedTemplate {
            tag,
            site,
            cooked,
            raw,
            exprs,
        } => {
            s_expr(tag);
            for x in exprs.iter_mut() {
                s_expr(x);
            }
        }
        ExprKind::Array { items } => {
            for x in items.iter_mut() {
                s_array_item(x);
            }
        }
        ExprKind::Object { props } => {
            for x in props.iter_mut() {
                s_obj_prop(x);
            }
        }
        ExprKind::Fn { fn_ } => {}
        ExprKind::Class { cls } => {
            s_class(cls);
        }
        ExprKind::Decl { decl } => {}
        ExprKind::This { decl } => {}
        ExprKind::NewTarget { decl } => {}
        ExprKind::ImportMeta => {}
        ExprKind::SuperMember { prop, this, home } => {
            s_prop_key(prop);
        }
        ExprKind::Member {
            obj,
            prop,
            optional,
            layout,
            field,
        } => {
            s_expr(obj);
            s_prop_key(prop);
            *layout = None;
            *field = None;
        }
        ExprKind::Unary { op, e } => {
            s_expr(e);
        }
        ExprKind::Update { op, prefix, target } => {
            s_target(target);
        }
        ExprKind::Binary { op, l, r, numeric } => {
            s_expr(l);
            s_expr(r);
            *numeric = None;
        }
        ExprKind::Logical { op, l, r } => {
            s_expr(l);
            s_expr(r);
        }
        ExprKind::Cond { test, then, else_ } => {
            s_expr(test);
            s_expr(then);
            s_expr(else_);
        }
        ExprKind::Assign { op, target, value } => {
            s_target(target);
            s_expr(value);
        }
        ExprKind::Seq { exprs } => {
            for x in exprs.iter_mut() {
                s_expr(x);
            }
        }
        ExprKind::Call {
            callee,
            args,
            optional,
            direct,
            intrinsic,
            direct_eval,
        } => {
            s_expr(callee);
            for x in args.iter_mut() {
                s_arg(x);
            }
            *direct = None;
            *intrinsic = None;
        }
        ExprKind::New {
            callee,
            args,
            direct,
        } => {
            s_expr(callee);
            for x in args.iter_mut() {
                s_arg(x);
            }
            *direct = None;
        }
        ExprKind::SuperCall {
            args,
            this,
            new_target,
            func,
        } => {
            for x in args.iter_mut() {
                s_arg(x);
            }
        }
        ExprKind::Import { spec, options } => {
            s_expr(spec);
            if let Some(x) = options.as_mut() {
                s_expr(x);
            }
        }
        ExprKind::Yield { e, delegate } => {
            if let Some(x) = e.as_mut() {
                s_expr(x);
            }
        }
        ExprKind::Await { e } => {
            s_expr(e);
        }
        ExprKind::Decode { desc, e } => {
            s_expr(e);
        }
        ExprKind::Scratch { elem, body } => {}
        ExprKind::OptionalChain { e } => {
            s_expr(e);
        }
        ExprKind::PrivateIn { name, obj } => {
            s_expr(obj);
        }
        ExprKind::Named { name, e } => {
            s_expr(e);
        }
    }
    *(&mut v.ty) = TypeRef(0);
}

fn s_prop_key(v: &mut PropKey) {
    match v {
        PropKey::Name { name } => {}
        PropKey::Computed { e } => {
            s_expr(e);
        }
        PropKey::Private { name } => {}
    }
}

fn s_arg(v: &mut Arg) {
    match v {
        Arg::Arg { e } => {
            s_expr(e);
        }
        Arg::Spread { e } => {
            s_expr(e);
        }
    }
}

fn s_array_item(v: &mut ArrayItem) {
    match v {
        ArrayItem::Item { e } => {
            s_expr(e);
        }
        ArrayItem::Spread { e } => {
            s_expr(e);
        }
        ArrayItem::Hole => {}
    }
}

fn s_target(v: &mut Target) {
    match &mut v.kind {
        TargetKind::Decl { decl } => {}
        TargetKind::Member {
            obj,
            prop,
            layout,
            field,
        } => {
            s_expr(obj);
            s_prop_key(prop);
            *layout = None;
            *field = None;
        }
        TargetKind::Pattern { p } => {
            s_pattern(p);
        }
        TargetKind::SuperMember { prop, this, home } => {
            s_prop_key(prop);
        }
    }
}

fn s_obj_prop(v: &mut ObjProp) {
    match v {
        ObjProp::Init {
            key,
            value,
            shorthand,
        } => {
            s_prop_key(key);
            s_expr(value);
        }
        ObjProp::Method { key, fn_, role } => {
            s_prop_key(key);
        }
        ObjProp::Spread { e } => {
            s_expr(e);
        }
        ObjProp::Proto { value } => {
            s_expr(value);
        }
    }
}

fn s_class(v: &mut Class) {
    if let Some(x) = (&mut v.extends).as_mut() {
        s_expr(x);
    }
    for x in (&mut v.members).iter_mut() {
        s_class_member(x);
    }
    *(&mut v.layout) = None;
}

fn s_class_member(v: &mut ClassMember) {
    match v {
        ClassMember::Method {
            key,
            fn_,
            static_,
            role,
        } => {
            s_prop_key(key);
        }
        ClassMember::PrivateMethod {
            decl,
            fn_,
            static_,
            role,
        } => {}
        ClassMember::FieldKey { key, decl, static_ } => {
            s_expr(key);
        }
        ClassMember::PrivateField { decl, static_ } => {}
    }
}

fn s_stmt(v: &mut Stmt) {
    match &mut v.kind {
        StmtKind::Expr { e } => {
            s_expr(e);
        }
        StmtKind::Declare { decl, init } => {
            if let Some(x) = init.as_mut() {
                s_expr(x);
            }
        }
        StmtKind::Destructure {
            pattern,
            init,
            declaring,
        } => {
            s_pattern(pattern);
            s_expr(init);
        }
        StmtKind::Block { body } => {
            s_block(body);
        }
        StmtKind::If { test, then, else_ } => {
            s_expr(test);
            s_stmt(then);
            if let Some(x) = else_.as_mut() {
                s_stmt(x);
            }
        }
        StmtKind::While { test, body, label } => {
            s_expr(test);
            s_stmt(body);
        }
        StmtKind::DoWhile { body, test, label } => {
            s_stmt(body);
            s_expr(test);
        }
        StmtKind::For {
            init,
            test,
            update,
            body,
            label,
            per_iteration,
        } => {
            if let Some(x) = init.as_mut() {
                s_stmt(x);
            }
            if let Some(x) = test.as_mut() {
                s_expr(x);
            }
            if let Some(x) = update.as_mut() {
                s_expr(x);
            }
            s_stmt(body);
        }
        StmtKind::ForIn {
            target,
            init,
            obj,
            body,
            label,
        } => {
            s_for_target(target);
            if let Some(x) = init.as_mut() {
                s_expr(x);
            }
            s_expr(obj);
            s_stmt(body);
        }
        StmtKind::ForOf {
            target,
            iter,
            body,
            label,
            await_,
            array_fast,
        } => {
            s_for_target(target);
            s_expr(iter);
            s_stmt(body);
            *array_fast = false;
        }
        StmtKind::Switch {
            disc,
            cases,
            label,
            exhaustive,
        } => {
            s_expr(disc);
            for x in cases.iter_mut() {
                s_switch_case(x);
            }
            *exhaustive = false;
        }
        StmtKind::Break { label } => {}
        StmtKind::Continue { label } => {}
        StmtKind::Return { e } => {
            if let Some(x) = e.as_mut() {
                s_expr(x);
            }
        }
        StmtKind::Throw { e } => {
            s_expr(e);
        }
        StmtKind::Try {
            body,
            catch_param,
            catch_body,
            finally,
            catch_default,
        } => {
            s_block(body);
            if let Some(x) = catch_param.as_mut() {
                s_pattern(x);
            }
            if let Some(x) = catch_body.as_mut() {
                s_block(x);
            }
            if let Some(x) = finally.as_mut() {
                s_block(x);
            }
            if let Some(x) = catch_default.as_mut() {
                s_expr(x);
            }
        }
        StmtKind::Labeled { label, body } => {
            s_stmt(body);
        }
        StmtKind::FnDecl { decl, fn_, annex_b } => {}
        StmtKind::ClassDecl { decl, cls } => {
            s_class(cls);
        }
        StmtKind::Debugger => {}
        StmtKind::Empty => {}
        StmtKind::DefineField { key, value } => {
            if let Some(x) = value.as_mut() {
                s_expr(x);
            }
        }
        StmtKind::DefinePrivate { decl, value } => {
            if let Some(x) = value.as_mut() {
                s_expr(x);
            }
        }
        StmtKind::StaticBlock { fn_ } => {}
    }
}

fn s_block(v: &mut Block) {
    for x in (&mut v.stmts).iter_mut() {
        s_stmt(x);
    }
}

fn s_switch_case(v: &mut SwitchCase) {
    if let Some(x) = (&mut v.test).as_mut() {
        s_expr(x);
    }
    for x in (&mut v.body).iter_mut() {
        s_stmt(x);
    }
}

fn s_for_target(v: &mut ForTarget) {
    match v {
        ForTarget::Assign { t } => {
            s_target(t);
        }
        ForTarget::Declare { pattern } => {
            s_pattern(pattern);
        }
    }
}

fn s_pattern(v: &mut Pattern) {
    match &mut v.kind {
        PatternKind::Decl { decl } => {}
        PatternKind::Target { t } => {
            s_target(t);
        }
        PatternKind::Object { props, rest } => {
            for x in props.iter_mut() {
                s_pattern_prop(x);
            }
            if let Some(x) = rest.as_mut() {
                s_pattern(x);
            }
        }
        PatternKind::Array { items, rest } => {
            for x in items.iter_mut() {
                s_pattern_item(x);
            }
            if let Some(x) = rest.as_mut() {
                s_pattern(x);
            }
        }
    }
    *(&mut v.ty) = TypeRef(0);
}

fn s_pattern_prop(v: &mut PatternProp) {
    s_prop_key((&mut v.key));
    s_pattern((&mut v.value));
    if let Some(x) = (&mut v.default).as_mut() {
        s_expr(x);
    }
}

fn s_pattern_item(v: &mut PatternItem) {
    match v {
        PatternItem::Item { p, default } => {
            s_pattern(p);
            if let Some(x) = default.as_mut() {
                s_expr(x);
            }
        }
        PatternItem::Hole => {}
    }
}

/// Resets every piece of type information to its default, leaving the
/// HIR that the same program without annotations produces.
pub fn strip(program: &mut Program) {
    let v = program;
    (&mut v.types).clear();
    (&mut v.layouts).clear();
    (&mut v.descriptors).clear();
    for x in (&mut v.decls).iter_mut() {
        s_decl(x);
    }
    for x in (&mut v.functions).iter_mut() {
        s_function(x);
    }
}
